SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END launch_cohort, MONTH(launch_date) launch_month, SUM(stock_qty) total_stock_qty, AVG(price) avg_price FROM products WHERE supplier_id IN (7, 16, 18) GROUP BY CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END, MONTH(launch_date) ORDER BY launch_month DESC, launch_cohort LIMIT 20;
